 cards.append('<article data-group="'+html.escape(row['group'],quote=True)+'"><a href="'+row['file']+'">'+image+'</a><div class="caption"><small>'+html.escape(row['group'])+'</small><h2>'+html.escape(row['title'])+'</h2><p>'+html.escape(caption)+'</p>'+before+'</div></article>')
